    if ("E_BAD_INPUT" === err.type) {
      console.error("Error:");
      console.error();
      console.error(err.message);
      console.error();
      process.exit(1);
      return;
    }

    if (err.code) {
      console.error(`${err.code}:`);
      console.error();
      console.error(err.message);
      if ("E_BREAK_CHANGE" === err.code) {
        console.error(
          `select an additional coin, or pass --break-change to redenominate`,
        );
      }
      console.error();
      process.exit(1);
      return;
    }

    console.error("Fail:");
    console.error(err.stack || err);
    if (err.failedTx) {
      console.error(
        "Failed Transaciton: (inspect at https://live.blockcypher.com/dash/decodetx/)",
      );
      console.error(err.failedTx);
    }
    if (err.response) {
      let resp = err.response;
      if (resp.toJSON) {
        resp = resp.toJSON();
      }
      console.error(resp);
    }
    process.exit(1);
  });

